نقش سازمانی: مدیر خرید و تدارکات (procurement_manager)

درخواست کاربر:
عملکرد تأمین‌کنندگان اصلی را با هم مقایسه کن. کدام بهتر است؟ (مدیر خرید — شرکت مس کالسیمین)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "supplier_performance",
      "description": "عملکرد تأمین‌کنندگان: تأخیر، کیفیت، قیمت",
      "dimensions": [
        "supplier",
        "period"
      ],
      "measures": [
        "on_time_pct",
        "quality_score",
        "lead_time_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "supplier_on_time",
      "description": "نرخ تحویل به‌موقع",
      "formula": "تحویل‌های به‌موقع / کل تحویل‌ها",
      "unit": "درصد",
      "dimensions": [
        "supplier"
      ]
    },
    {
      "metric": "purchase_price_variance",
      "description": "انحراف قیمت خرید",
      "formula": "(قیمت واقعی - قیمت برنامه‌ریزی‌شده) / قیمت برنامه‌ریزی‌شده",
      "unit": "درصد",
      "dimensions": [
        "item"
      ]
    },
    {
      "metric": "lead_time",
      "description": "زمان تحویل تأمین‌کننده",
      "formula": "روز از سفارش تا تحویل",
      "unit": "روز",
      "dimensions": [
        "supplier",
        "item"
      ]
    }
  ],
  "business_context": [
    "خرید مواد اولیه، قطعات یدکی و مصرفی معدن از تأمین‌کنندگان داخلی و خارجی",
    "قراردادهای بلندمدت و سالانه با تأمین‌کنندگان اصلی",
    "تأمین قطعات حیاتی تجهیزات معدنی با زمان تحویل طولانی"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "supplier_performance",
    "filters": {
      "period": "last_3_months"
    }
  }
}

TOOL_OBSERVATION:
{
  "suppliers": [
    {
      "name": "تأمین‌کننده A",
      "on_time": 79,
      "ppv": 2.7,
      "lead_time": 27
    },
    {
      "name": "تأمین‌کننده B",
      "on_time": 85,
      "ppv": 0.8,
      "lead_time": 39
    },
    {
      "name": "تأمین‌کننده C",
      "on_time": 98,
      "ppv": 10.8,
      "lead_time": 38
    },
    {
      "name": "تأمین‌کننده D",
      "on_time": 85,
      "ppv": 11.2,
      "lead_time": 34
    },
    {
      "name": "تأمین‌کننده E",
      "on_time": 79,
      "ppv": 0.1,
      "lead_time": 26
    }
  ]
}

نقش سازمانی: مدیر خرید و تدارکات (procurement_manager)

درخواست کاربر:
انحراف قیمت لاستیک شاول 16.3% است. ریشهٔ این افزایش کجاست؟ (مدیر خرید — شرکت مس کالسیمین)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "purchase_orders",
      "description": "سفارشات خرید به تفکیک تأمین‌کننده و قلم",
      "dimensions": [
        "supplier",
        "item",
        "period"
      ],
      "measures": [
        "quantity",
        "unit_price",
        "total_cost"
      ]
    },
    {
      "dataset": "contracts",
      "description": "قراردادهای خرید: قیمت، حجم، مدت",
      "dimensions": [
        "supplier",
        "item"
      ],
      "measures": [
        "volume",
        "price_per_unit",
        "start_date",
        "end_date"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "purchase_price_variance",
      "description": "انحراف قیمت خرید",
      "formula": "(قیمت واقعی - قیمت برنامه‌ریزی‌شده) / قیمت برنامه‌ریزی‌شده",
      "unit": "درصد",
      "dimensions": [
        "item"
      ]
    }
  ],
  "business_context": [
    "خرید مواد اولیه، قطعات یدکی و مصرفی معدن از تأمین‌کنندگان داخلی و خارجی",
    "قراردادهای بلندمدت و سالانه با تأمین‌کنندگان اصلی",
    "تأمین قطعات حیاتی تجهیزات معدنی با زمان تحویل طولانی"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "purchase_orders",
    "filters": {
      "period": "curr_month",
      "ppv_above_zero": true
    }
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "contracts",
    "filters": {
      "item": "لاستیک شاول"
    }
  }
}

TOOL_OBSERVATION:
{
  "contract_status": "قرارداد سالانه با قیمت ثابت — منقضی شده و قرارداد جدید با قیمت بالاتر بسته شده",
  "market_note": "قیمت جهانی لاستیک ۱۲٪ افزایش یافته"
}

نقش سازمانی: مدیر خرید و تدارکات (procurement_manager)

درخواست کاربر:
لاستیک شاول را از کدام تأمین‌کننده بخریم؟ (مدیر خرید — شرکت مس شهید باهنر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "contracts",
      "description": "قراردادهای خرید: قیمت، حجم، مدت",
      "dimensions": [
        "supplier",
        "item"
      ],
      "measures": [
        "volume",
        "price_per_unit",
        "start_date",
        "end_date"
      ]
    },
    {
      "dataset": "inventory_critical",
      "description": "موجودی قطعات حیاتی و نقطهٔ سفارش",
      "dimensions": [
        "item"
      ],
      "measures": [
        "current_stock",
        "reorder_point",
        "lead_time_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "lead_time",
      "description": "زمان تحویل تأمین‌کننده",
      "formula": "روز از سفارش تا تحویل",
      "unit": "روز",
      "dimensions": [
        "supplier",
        "item"
      ]
    },
    {
      "metric": "critical_stockout_risk",
      "description": "ریسک کمبود قطعات حیاتی",
      "formula": "موجودی / مصرف روزانه",
      "unit": "روز",
      "dimensions": [
        "item"
      ]
    }
  ],
  "business_context": [
    "خرید مواد اولیه، قطعات یدکی و مصرفی معدن از تأمین‌کنندگان داخلی و خارجی",
    "قراردادهای بلندمدت و سالانه با تأمین‌کنندگان اصلی",
    "تأمین قطعات حیاتی تجهیزات معدنی با زمان تحویل طولانی"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "contracts",
    "filters": {
      "item": "لاستیک شاول"
    }
  }
}

TOOL_OBSERVATION:
{
  "supplier_A": {
    "price": 2600,
    "lead_time": 16
  },
  "supplier_B": {
    "price": 2372.390580185561,
    "lead_time": 32
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "inventory_critical",
    "filters": {
      "item": "لاستیک شاول"
    }
  }
}

TOOL_OBSERVATION:
{
  "current_stock_days": 32,
  "reorder_point_days": 30
}

